nodes.css:
.wrap { position: absolute; inset: 0; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 34px; }
.kicker { font-family: JetBrains Mono, DejaVu Sans Mono, monospace; font-size: 17px; font-weight: 600;
  letter-spacing: 0.3em; color: #d9a441;
  animation: rise 0.5s cubic-bezier(0.16,1,0.3,1) 0.1s both; }
.head { font-family: Archivo, Inter, DejaVu Sans; font-size: 92px; font-weight: 800;
  letter-spacing: -0.035em; color: #f4f1ea; line-height: 1;
  animation: rise 0.6s cubic-bezier(0.16,1,0.3,1) 0.2s both; }
.head em { font-style: normal; color: #d9a441; }
.row { display: flex; flex-direction: row; align-items: center; gap: 26px; }
.btn { display: flex; flex-direction: row; align-items: center; gap: 14px;
  padding: 18px 34px; border-radius: 999px; background: rgba(12,13,16,0.92);
  border: 1.5px solid #d9a441; }
.ghost { display: flex; flex-direction: row; align-items: center; gap: 14px;
  padding: 18px 34px; border-radius: 999px; background: rgba(12,13,16,0.92);
  border: 1.5px solid rgba(244,241,234,0.3); }
.dot { width: 10px; height: 10px; border-radius: 999px; background: #d9a441; }
.txt { font-family: JetBrains Mono, DejaVu Sans Mono, monospace; font-size: 19px; font-weight: 700;
  letter-spacing: 0.2em; color: #f4f1ea; }
.b1 { animation: rise 0.5s cubic-bezier(0.16,1,0.3,1) 0.5s both; }
.b2 { animation: rise 0.5s cubic-bezier(0.16,1,0.3,1) 0.62s both; }
.foot { font-family: JetBrains Mono, DejaVu Sans Mono, monospace; font-size: 15px; letter-spacing: 0.26em;
  color: #9a978e;
  animation: rise 0.5s cubic-bezier(0.16,1,0.3,1) 0.74s both; }
@keyframes rise { from { opacity: 0; transform: translateY(10px) } to { opacity: 1; transform: translateY(0) } }
